1	package retention
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	func writeStateFile(t *testing.T, dir, content string) {
13		t.Helper()
14		if err := os.WriteFile(filepath.Join(dir, stateFileName), []byte(content), 0o600); err != nil {
15			t.Fatal(err)
16		}
17	}
18	
19	func readStateFile(t *testing.T, dir string) string {
